text_score.text:
def text_score(doc: dict, attrs: dict) -> float:
    n = doc["norm"]
    score = 0.0
    weights = {"country": 2.0, "platform": 4.0, "region": 3.0, "task": 2.0}
    for key, weight in weights.items():
        vs = variants(attrs.get(key, ""))
        if vs and any(v in n for v in vs):
            score += weight
    return score

similarity.text:
def similarity(a: str, b: str) -> float:
    a, b = clean(a), clean(b)
    if not a or not b:
        return 0.0
    sa = set(re.findall(r"[a-z0-9]+|[\u4e00-\u9fff]{2}", a))
    sb = set(re.findall(r"[a-z0-9]+|[\u4e00-\u9fff]{2}", b))
    jac = len(sa & sb) / max(1, len(sa | sb))
    return max(jac, SequenceMatcher(None, a, b).ratio())

choose_trend.text:
def choose_trend(day: str, cache: dict[str, list[Event]]) -> tuple[str, list[Event]]:
    current = [e for e in cache[day] if e.decision=="纳入" and (e.country not in CN_NAMES)]
    if not current: return "当日无可核验外（台）重点主线", []
    best = []
    for seed in current:
        chain=[]
        for d, events in cache.items():
            if datetime.strptime(d,"%Y.%m.%d") > datetime.strptime(day,"%Y.%m.%d"): continue
            matches=[e for e in events if e.decision=="纳入" and e.country==seed.country and (clean(seed.platform) in clean(e.platform) or clean(e.platform) in clean(seed.platform))]
            if matches: chain.append(matches[0])
        if len({e.date for e in chain}) > len({e.date for e in best}): best=chain
    label = f"{best[-1].country}{best[-1].platform}活动主线" if best else "外（台）活动主线"
    return label, best

_vote.text:
def _vote(values: dict[str, object], prefer: tuple = ("R", "O", "P"), eq=lambda a, b: a == b) -> Field:
    vals = {k: v for k, v in values.items() if v not in (None, "")}
    if not vals:
        return Field("", [])
    groups: list[tuple[object, list[str]]] = []
    for k, v in vals.items():
        for g in groups:
            if eq(g[0], v):
                g[1].append(k)
                break
        else:
            groups.append((v, [k]))
    rank = {s: i for i, s in enumerate(prefer)}
    groups.sort(key=lambda g: (-len(g[1]), min(rank.get(s, 9) for s in g[1])))
    value, support = groups[0]
    conflicts = {s: v for v, ss in groups[1:] for s in ss}
    return Field(value, support, conflicts)

verify.text:
def verify(ev: Event) -> None:
    t, o, p = ev.track, ev.o, ev.p
    alt = t.alts[ev.alt_index] if t else None
    ev.anomalies = list(t.anomalies) if t else []
    reasons = []

    # 平台 ------------------------------------------------------------------
    if t:
        platform = t.platform
    else:
        platform = next((m.platform or (m.candidates[0] if m.candidates else "") for m in (o, p) if m and m.candidates), "")
    psup = []
    if t:
        psup.append("R")
    for k, m in (("O", o), ("P", p)):
        if not m:
            continue
        if platform and (platform in m.candidates or (m.is_fuzzy and (not m.fuzzy_cats or L.platform_category(platform) in m.fuzzy_cats))):
            psup.append(k)
    ev.fields["platform"] = Field(platform, psup)
    kind = L.platform_kind(platform) if platform else (ev.kind or "")
    ev.kind = kind

    # 国家/地区 ---------------------------------------------------------------
    cvals = {}
    if t:
        cvals["R"] = t.country
    if o:
        cvals["O"] = o.country
    if p:
        cvals["P"] = p.country
    cf = _vote(cvals)
    plaus = L.platform_countries(platform)
    if plaus and cf.value and cf.value not in plaus:
        # 多数结果与平台隶属常识冲突：尝试采用符合常识的少数值
        alt_vals = [v for v in cvals.values() if v in plaus]
        if alt_vals:
            v = Counter(alt_vals).most_common(1)[0][0]
            cf = Field(v, [k for k, x in cvals.items() if x == v], {k: x for k, x in cvals.items() if x != v},
                       note="多数国家值与平台隶属不符，按主体—平台一致性校正")
    if t and not t.country_ok and "R" in cf.support:
        cf.support.remove("R")
        cf.note = (cf.note + "；" if cf.note else "") + "雷达主体—平台错配，不计入支持"
    if t and not t.country_ok and cf.value != t.country:
        cf.conflicts["R"] = t.country
    ev.fields["country"] = cf

    # 海域 ------------------------------------------------------------------
    cand = []
    for m in (o, p):
        if m and m.region:
            cand.append(m.region)
    if t:
        cand += [a.region for a in t.alts]
    cand = list(dict.fromkeys(cand))

    def supports(src: str, region: str) -> bool:
        if src == "R":
            return any(a.region == region or (a.lon is not None and not L.is_broad(region) and region_fits(region, a.lon, a.lat))
                       for a in t.alts)
        m = o if src == "O" else p
        return m.region == region

    def dir_supports(src: str, direction: str) -> bool:
        if src == "R":
            return any(a.direction == direction for a in t.alts)
        m = o if src == "O" else p
        return L.region_direction(m.region) == direction

    srcs = ev.sources
    best = None
    for r in cand:
        sup = [s for s in srcs if supports(s, r)]
        d = L.region_direction(r)
        dsup = [s for s in srcs if dir_supports(s, d)]
        key = (len(dsup), len(sup), not L.is_broad(r), "O" in sup, "R" in sup)
        if best is None or key > best[0]:
            best = (key, r, sup, dsup)
    if best:
        _, region, rsup, dsup = best
        direction = L.region_direction(region)
        rconf = {}
        for s in srcs:
            if s not in dsup:
                rconf[s] = (t.alts[0].region if s == "R" else (o if s == "O" else p).region)
        note = ""
        if len(rsup) < 2 and len(dsup) >= 2:
            note = "具体区域单源给出，活动方向多源一致"
        reg_conf = {}
        for s in srcs:
            if s in rsup:
                continue
            if s == "R":
                other = [a.region for a in t.alts if a.direction == direction] or [t.alts[0].region]
                if not any(L.is_broad(x) for x in other):
                    reg_conf["R"] = other[0]
            else:
                mreg = (o if s == "O" else p).region
                if mreg and not L.is_broad(mreg):
                    reg_conf[s] = mreg
        ev.fields["region"] = Field(region, rsup, reg_conf, note)
        ev.fields["direction"] = Field(direction, dsup, rconf)
        if t:
            for i, a in enumerate(t.alts):
                if a.region == region or (a.lon is not None and not L.is_broad(region) and region_fits(region, a.lon, a.lat)):
                    ev.alt_index = i
                    break
            else:
                for i, a in enumerate(t.alts):
                    if a.direction == direction:
                        ev.alt_index = i
                        break
            alt = t.alts[ev.alt_index]
            if len(t.alts) > 1:
                ev.anomalies.append(f"已采用与文本一致的点迹/区域“{alt.region}”，剔除其余异常点迹")
            if "R" not in dsup:
                ev.anomalies.append(f"雷达区域“{alt.region}”与文本多数结论“{region}”冲突，按区域错配噪声处理")
    else:
        ev.fields["region"] = Field("", [])
        ev.fields["direction"] = Field("", [])

    # 任务 / 数量 / 时间 -------------------------------------------------------
    tv = {}
    if t:
        tv["R"] = t.task
    for k, m in (("O", o), ("P", p)):
        if m and m.task:
            tv[k] = L.normalize_task(m.task, kind)
    ev.fields["task"] = _vote(tv, eq=lambda a, b: a == b)
    nv = {}
    if t:
        nv["R"] = t.count
    for k, m in (("O", o), ("P", p)):
        if m and m.count:
            nv[k] = m.count
    ev.fields["count"] = _vote(nv)
    sv, evv = {}, {}
    if t:
        sv["R"], evv["R"] = alt.start, alt.end
    for k, m in (("O", o), ("P", p)):
        if m and m.start:
            sv[k] = m.start
        if m and m.end:
            evv[k] = m.end
    ev.fields["start"] = _vote(sv, eq=_time_eq)
    ev.fields["end"] = _vote(evv, eq=_time_eq)
    actions = [m.action for m in (o, p) if m and m.action != "活动"]
    ev.fields["action"] = Field(actions[0] if actions else "活动", [k for k, m in (("O", o), ("P", p)) if m and m.action != "活动"])
    cs = next((m.callsign for m in (o, p) if m and m.callsign), "")
    ev.fields["callsign"] = Field(cs or (t.hull if t else ""), ["O"] if cs else (["R"] if t else []))

    # 判定 ------------------------------------------------------------------
    if len(srcs) < 2:
        reasons.append(f"仅{''.join(srcs)}单一来源，无法交叉核验")
    for name, label in (("platform", "平台"), ("country", "国家/地区"), ("direction", "活动方向")):
        f = ev.fields[name]
        if not f.value:
            reasons.append(f"{label}缺失")
        elif len(f.support) < 2:
            reasons.append(f"{label}“{f.value}”仅{len(f.support)}类来源支持")
        elif f.conflicts and len(f.support) < 2:
            reasons.append(f"{label}存在无法消解的冲突")
    ev.reasons = reasons
    ev.status = "可信" if not reasons else "排除"

build_mainline.text:
def build_mainline(node: str, events_by_day: dict[str, list[Event]]) -> Mainline | None:
    node_d = parse_day(node)
    today = [e for e in events_by_day.get(node, []) if e.in_core and e.get("country") not in ("中国", "")]
    if not today:
        return None
    hist: dict[tuple, list[Event]] = {}
    for day, evs in events_by_day.items():
        if parse_day(day) > node_d:
            continue  # 严格禁止使用节点之后的信息
        for e in evs:
            if e.in_core and e.get("country") not in ("中国", ""):
                hist.setdefault((e.get("country"), e.get("platform")), []).append(e)
    best: Mainline | None = None
    for key in {(e.get("country"), e.get("platform")) for e in today}:
        evs = sorted(hist.get(key, []), key=lambda e: (parse_day(e.day), e.get("start")))
        days = sorted({parse_day(e.day) for e in evs})
        # ≥15 日断档视为新线索：只保留最近一次断档之后的部分
        cut = 0
        for i in range(1, len(days)):
            if (days[i] - days[i - 1]).days >= 15:
                cut = i
        days = days[cut:]
        evs = [e for e in evs if parse_day(e.day) >= days[0]]
        if len(days) < 3:
            continue
        dirs = Counter(e.direction for e in evs)
        score = len(days) + 0.6 * len(dirs) + PRIORITY.get(key[0], 0.5) + 0.02 * (days[-1] - days[0]).days
        if best is None or score > best.score:
            best = Mainline(key[0], key[1], evs, score=score)
    if best is None:
        return None
    _phase(best, node)
    return best

_phase.text:
def _phase(ml: Mainline, node: str) -> None:
    days = ml.days
    segs = _segments(days)
    # 方向/区域变化也作为阶段切分依据
    by_day: dict[date, list[Event]] = {}
    for e in ml.events:
        by_day.setdefault(parse_day(e.day), []).append(e)

    def main_dir(ds):
        return Counter(e.direction for d in ds for e in by_day[d]).most_common(1)[0][0]

    pieces: list[list[date]] = []
    for seg in segs:
        cur = [seg[0]]
        for d in seg[1:]:
            if main_dir([d]) != main_dir(cur) and len(cur) >= 1:
                pieces.append(cur)
                cur = [d]
            else:
                cur.append(d)
        pieces.append(cur)
    # 合并到 2—3 个阶段
    while len(pieces) > 3:
        i = min(range(len(pieces) - 1), key=lambda k: len(pieces[k]) + len(pieces[k + 1]))
        pieces[i:i + 2] = [pieces[i] + pieces[i + 1]]
    if len(pieces) == 1 and len(days) >= 3:
        mid = len(days) // 2 if len(days) > 3 else 2
        pieces = [days[:mid], days[mid:]]
    ml.phases = [Phase(p[0], p[-1], [e for d in p for e in by_day[d]]) for p in pieces]

    gaps = [(b - a).days for a, b in zip(days, days[1:])]
    dirs = [ph.directions[0] for ph in ml.phases]
    last_events = by_day[days[-1]]
    leaving = any("离开" in e.get("action") for e in last_events)
    if leaving:
        pattern = "离开"
    elif len(set(dirs)) > 1:
        pattern = "转移"
    elif any(8 <= g <= 14 for g in gaps):
        pattern = "间歇"
    else:
        pattern = "持续"
    ml.pattern = pattern
    span = (days[-1] - days[0]).days + 1
    first, last = days[0], days[-1]
    dir_text = "、".join(dict.fromkeys(dirs))
    ml.judgement = (f"{ml.country}{ml.platform}自{first.month}月{first.day}日至{last.month}月{last.day}日（跨度{span}天）"
                    f"共在{len(days)}个日期出现可信活动，活动方向涉及{dir_text}，总体呈“{pattern}”态势。")

adjudicate.text:
def adjudicate(track,a,b):
    f=track['fields']; conflicts=list(track['conflicts'])+claims_relation(a,b); corrections=[]
    if track['kind']=='舰船':
        candidates=[r for r in track['region_values'] if region_relation(r,a['region'])!='conflict' and region_relation(r,b['region'])!='conflict']
        if len(candidates)==1:
            region=candidates[0]
            bad=[r for r in track['raw_rows'] if region_relation(str(r['data']['活动区域']),region)=='conflict']
            if bad:
                # Independent text agreement + an isolated substitution in an
                # otherwise identical observation tuple. Never count votes.
                text_agreement=region_relation(a['region'],b['region']) in ('exact','contains')
                for r in bad:
                    d=r['data']; peers=[p for p in track['raw_rows'] if p['row']!=r['row'] and p['data']['活动区域']==region and p['data']['首点时间']==d['首点时间'] and p['data']['结束时间']==d['结束时间']]
                    if text_agreement and len(bad)==1 and len(peers)>=2:
                        corrections.append({'row':r['row'],'field':'活动区域','raw':d['活动区域'],'accepted':region,'reason':'同批同起止孤立区域替换；两类文本区域兼容，并有相同时段的连续同区域观测；隔离该行，不以多数票认定'})
                    else: conflicts.append('雷达区域冲突不能由连续性与两类文本共同消解')
        else:
            region=''; conflicts.append('三源无唯一兼容具体区域')
    else:
        rel=region_relation(a['region'],b['region'])
        region=a['region'] if rel=='exact' else direction(a['region']) if rel=='contains' else ''
        if not region: conflicts.append('文本具体区域不能建立包含关系')
        # Geographic envelopes only support the sea; a finer location needs two
        # textual classes. We deliberately do not infer precise sea areas.
        if region and coord_support(region,track['xy']) is False: conflicts.append('文本区域与雷达坐标明确冲突')
    checks={}
    for key in ['country','platform','quantity','task']:
        value=f[key]; sources=['雷达'] if value is not None else []
        for c in (a,b):
            cv=c['tasks'] if key=='task' else c[key]
            if (key=='task' and value in cv) or (key!='task' and cv==value): sources.append(c['source'])
        checks[key]={'value':value,'sources':sources}
        if len(set(sources))<2:
            if key=='task' and not a['tasks'] and not b['tasks']:
                checks[key]={'value':'任务未核实','sources':[],'status':'unknown','candidate':value,'reason':'两文本只证实活动，雷达具体任务为单源候选；不输出为事实'}
            else: conflicts.append(key+'不足两类来源支持')
    time_sources=['雷达']; final_interval=track['interval']
    for c in (a,b):
        if time_relation(track['interval'],c['interval'])=='exact': time_sources.append(c['source'])
    if track['kind']=='飞机' and time_relation(a['interval'],b['interval'])=='exact' and all(x is not None for x in a['interval']) and a['interval'][0]<=track['interval'][0] and a['interval'][1]>=track['interval'][1]:
        final_interval=a['interval']; time_sources=[a['source'],b['source']]
        if time_relation(final_interval,track['interval'])=='exact': time_sources.append('雷达')
    checks['activity_window']={'value':final_interval,'sources':time_sources,'radar_observation_window':track['interval'],'note':'雷达位置时间不是起飞/降落时间；文本一致时段可包含部分观测'}
    if len(time_sources)<2: conflicts.append('活动起止时段不足两类来源支持')
    region_sources=[]
    if region:
        region_sources=[c['source'] for c in (a,b) if region_relation(c['region'],region) in ('exact','contains')]
        if track['kind']=='舰船' or coord_support(region,track['xy']) is True: region_sources.append('雷达')
    checks['region']={'value':region,'sources':region_sources,'specificity_note':'飞机单文本细分区域仅保留为候选；宽容包络不证明具体地点'}
    if len(set(region_sources))<2: conflicts.append('区域不足两类来源支持')
    checks['date']={'value':track['date'],'sources':['雷达',a['source'],b['source']]}
    return dict(facts=checks,region=region,direction=direction(region),conflicts=list(dict.fromkeys(conflicts)),corrections=corrections)

regions_in.text:
def regions_in(s):
    hits=[]
    for r in REGIONS:
        if r in s and not any(r in x for x in hits): hits.append(r)
    # A sentence can explicitly give core sea + its finer place.
    return [r for r in hits if not (r in ('东海','南海','黄海') and any(x!=r and direction(x)==r for x in hits))]

canon_platform.text:
def canon_platform(name):
    s=normal(name)
    code=re.match(r'(F/A\S+)',str(name))
    if code: return normal(code.group(1).split('“')[0])
    m=re.match(r'(?:[A-Z]+[0-9]+[A-Z]*(?:/[A-Z]+)?|[0-9]+[A-Z]*|歼[0-9]+[A-Z]*|轰[0-9]+[A-Z]*|运[0-9]+|空警[0-9]+|无侦[0-9]+|直[0-9]+|苏[0-9]+[A-Z]*|图[0-9]+[A-Z]*|米格[0-9]+[A-Z]*|伊尔[0-9]+|幻影[0-9]+[0-9]*|福克[0-9]+)',s)
    if m: return m.group()
    for suffix in ['舰载战斗机','多用途战斗机','反潜巡逻机','空中预警机','预警与控制机','空中预警管制机','导弹驱逐舰','导弹护卫舰','综合补给舰','航空母舰','直升机母舰','常规潜艇','攻击核潜艇','导弹巡洋舰','两栖攻击舰','近海巡逻舰','多用途巡逻舰','反潜护卫舰','坦克登陆舰','船坞登陆舰','船坞运输舰','电子侦察船','轻型护卫舰','濒海战斗舰']:
        if s.endswith(suffix): s=s[:-len(suffix)]; break
    return s.rstrip('型号级')

times_in.text:
def times_in(s):
    vals=[]
    for m in re.finditer(r'(\d{1,2})\s*(?:时(?:\s*(\d{1,2})\s*分)?|:\s*(\d{2}))',s):
        h=int(m.group(1)); mi=int(m.group(2) or m.group(3) or 0)
        if h<24 and mi<60: vals.append((h*60+mi,m.group(),m.start()))
    return vals

num.text:
def num(s):
    if s.isdigit(): return int(s)
    return {'一':1,'两':2,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10}.get(s)

parse_text.text:
def parse_text(t,day,lexicon):
    """Split explicit independent event sentences; retain shared formation scope."""
    body=t['fields'].get('正文',''); chunks=[]; current=''
    for part in re.findall(r'[^。；]+[。；]?',body):
        normalized=normal(part)
        explicit=any(re.search(re.escape(a)+r'(?![A-Z0-9])',normalized) for aa in lexicon.values() for a in aa)
        if current and explicit and regions_in(part) and re.search(r'执行|活动|进入|离开|开展|展开',part):
            chunks.append(current);current=part
        else: current+=part
    if current: chunks.append(current)
    claims=[]
    for index,chunk in enumerate(chunks):
        segment={**t,'fields':{**t['fields'],'正文':chunk}}
        cc=parse_segment(segment,day,lexicon)
        for c in cc:
            c['subevent_index']=index
            if len(chunks)>1: c['claim_id']=uid(t['file']+'|'+c['platform']+'|'+str(index))
            c['entity_kind']='named_hull' if re.search(re.escape(c['platform'])+r'号',normal(chunk)) and not re.search(r'经国',c['platform']) else 'platform_type'
            c['date_basis']='explicit_body_date' if re.search(r'2025年\d+月\d+日',chunk) else 'same-day_file_date'
        claims.extend(cc)
    return claims

distance.text:
def distance(a,b):
    x1,y1=a; x2,y2=b
    dlat=math.radians(y2-y1); dlon=math.radians(x2-x1)
    z=math.sin(dlat/2)**2+math.cos(math.radians(y1))*math.cos(math.radians(y2))*math.sin(dlon/2)**2
    return 6371*2*math.asin(min(1,math.sqrt(z)))

radar_time.text:
def radar_time(v):
    try: return datetime.strptime(str(v),'%Y.%m.%d %H:%M:%S')
    except ValueError: return None

reconstruct_radar.text:
def reconstruct_radar(day):
    batches=defaultdict(list)
    for r in day['radar']: batches[(r['sheet'],str(r['data']['批号']))].append(r)
    tracks=[]
    for (sheet,batch),rows in batches.items():
        clusters=[]
        if sheet=='飞机':
            for r in sorted(rows,key=lambda r:(float(r['data']['开始经度']),float(r['data']['开始纬度']),str(r['data']['位置时间']))):
                d=r['data']; anchor=(float(d['开始经度']),float(d['开始纬度']))
                match=next((c for c in clusters if distance(c['anchor'],anchor)<80),None)
